import{_ as e,a,b as i,c as r,d as n,e as o,f as s}from"./chunks/remove-4.C7c7eI4u.js";import{_ as l,o as g,c as d,a5 as h}from"./chunks/framework.CcrBcQWS.js";const w=JSON.parse('{"title":"2. Rail & Spring Nut","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/add-on/rail-spring-nut.md","filePath":"guides/add-on/rail-spring-nut.md","lastUpdated":1787021357000}'),p={name:"guides/add-on/rail-spring-nut.md"};function u(c,t,m,f,y,S){return g(),d("div",null,[...t[0]||(t[0]=[h('<h1 id="_2-rail-spring-nut" tabindex="-1">2. Rail &amp; Spring Nut <a class="header-anchor" href="#_2-rail-spring-nut" aria-label="Permalink to &quot;2. Rail &amp; Spring Nut&quot;">​</a></h1><p><strong>Goal:</strong> Mount your add-on hardware to the robot&#39;s top rail using spring nuts.</p><p><strong>Prerequisites:</strong> Step 1 <a href="/RBQ/nightly/guides/add-on/specifications.html">Specifications Check</a> is complete — the add-on is within payload and interface limits.</p><h2 id="what-you-need" tabindex="-1">What You Need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What You Need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Spring nuts</strong></td><td>MISUMI <strong>SHNTP5-5</strong> (<a href="https://kr.misumi-ec.com/vona2/detail/110302608410/?HissuCode=SHNTP5-5&amp;PNSearch=SHNTP5-5&amp;searchFlow=results2products&amp;list=PageSearchResult" target="_blank" rel="noreferrer">KR</a> · <a href="https://us.misumi-ec.com/vona2/detail/110302247640/?PNSearch=SHNTP5-5&amp;HissuCode=SHNTP5-5&amp;seriesCode=110302247640&amp;tab=drawingAndSpecifications&amp;Page=1" target="_blank" rel="noreferrer">US</a>)</td></tr><tr><td><strong>Bolts</strong></td><td>M5 bolts that match your add-on&#39;s mounting holes</td></tr><tr><td><strong>Rigid rod</strong></td><td><strong>≤ 4 mm diameter</strong>, for removal</td></tr></tbody></table><p>The robot top uses rails for mounting optional hardware (PTZ cameras, LiDAR, custom brackets). Spring nuts inserted into the rail slot give you threaded anchor points for M5 bolts.</p><h2 id="insert-a-spring-nut" tabindex="-1">Insert a Spring Nut <a class="header-anchor" href="#insert-a-spring-nut" aria-label="Permalink to &quot;Insert a Spring Nut&quot;">​</a></h2><ol><li><strong>Insert at an angle</strong> — slide the spring nut <strong>diagonally</strong> into the rail slot so it enters the internal channel.</li><li><strong>Press the protruding section</strong> — a portion of the nut may sit proud of the slot; press it down so the nut seats fully.</li><li><strong>Align with the rail</strong> — adjust the nut so it is aligned with the slot and can slide freely along the rail.</li></ol><figure style="text-align:center;"><img src="'+e+'" alt="Step 1 - diagonal insert" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 1 — diagonal insert</figcaption></figure><figure style="text-align:center;"><img src="'+a+'" alt="Step 2 - press the protruding section" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 2 — press the protruding section</figcaption></figure><figure style="text-align:center;"><img src="'+i+'" alt="Step 3 - align with the slot" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 3 — align with the slot</figcaption></figure><p>Slide the nut to the position where your add-on bracket should sit, then tighten the M5 bolt to fix the bracket.</p><h2 id="remove-a-spring-nut" tabindex="-1">Remove a Spring Nut <a class="header-anchor" href="#remove-a-spring-nut" aria-label="Permalink to &quot;Remove a Spring Nut&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><strong>Tool diameter:</strong> use a rigid rod <strong>no larger than 4 mm</strong> in diameter. A thicker tool can damage the nut or mar the rail slot.</p></div></div><ol><li><strong>Insert a rod</strong> — pass a rigid rod (<strong>≤ 4 mm</strong>) through the hole in the spring nut.</li><li><strong>Push against one wall</strong> — push the nut against one inner wall of the rail slot.</li><li><strong>Twist and lift</strong> — while holding it against that wall, twist and lift toward the opposite side so the nut clears the rail profile.</li><li><strong>Remove</strong> — withdraw the nut from the slot.</li></ol><figure style="text-align:center;"><img src="'+r+'" alt="Step 1 - rod through the hole" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 1 — rod through the hole</figcaption></figure><figure style="text-align:center;"><img src="'+n+'" alt="Step 2 - push to one wall" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 2 — push to one wall</figcaption></figure><figure style="text-align:center;"><img src="'+o+'" alt="Step 3 - twist and lift" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 3 — twist and lift</figcaption></figure><figure style="text-align:center;"><img src="'+s+'" alt="Step 4 - remove" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 4 — remove</figcaption></figure><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Hardware is mounted. Now register the add-on&#39;s mass and offset in the GUI:</p><p><strong><a href="/RBQ/nightly/guides/add-on/payload-setting.html">→ 3. Payload Setting</a></strong></p>',22)])])}const x=l(p,[["render",u]]);export{w as __pageData,x as default};
